private int calcDeduction(int theoreticalReceived, double highestLoss) {
        return ConfigBoolValues.LASER_RELAY_LOSS.isEnabled() ? MathHelper.ceil(theoreticalReceived * (highestLoss / 100)) : 0;
    }

